namespace sv_75a3f7126767415d8b29d6df3071e08a.Services;

public interface IRecipeService
{
    Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken);
}

public sealed class RecipeService : IRecipeService
{
    private static readonly Dictionary<int, List<Recipe>> Data = new()
    {
        [1] = new List<Recipe>
        {
            new(1, "Margherita Pizza", "Classic pizza with tomato sauce, mozzarella, and fresh basil.", 25),
            new(2, "Spaghetti Carbonara", "Creamy pasta with eggs, pecorino romano, guanciale, and black pepper.", 30),
            new(3, "Tiramisu", "Layered dessert with espresso-soaked ladyfingers and mascarpone cream.", 45),
            new(4, "Risotto alla Milanese", "Saffron-infused Arborio rice cooked slowly in broth.", 40),
        },
        [2] = new List<Recipe>
        {
            new(5, "Tacos al Pastor", "Marinated pork tacos with pineapple, cilantro, and onion.", 60),
            new(6, "Guacamole", "Fresh avocado dip with lime, cilantro, jalapeño, and tomato.", 10),
            new(7, "Chicken Enchiladas", "Corn tortillas filled with chicken and smothered in red sauce.", 50),
        },
        [3] = new List<Recipe>
        {
            new(8, "Sushi Rolls", "Vinegared rice and fresh fish wrapped in nori seaweed.", 55),
            new(9, "Miso Soup", "Traditional soup with dashi broth, tofu, and wakame seaweed.", 15),
            new(10, "Chicken Teriyaki", "Grilled chicken glazed with a sweet soy-based teriyaki sauce.", 35),
            new(11, "Ramen", "Rich pork broth noodle soup with chashu, egg, and green onions.", 120),
        },
    };

    public async Task<List<Recipe>> GetByCuisineAsync(int cuisineId, CancellationToken cancellationToken)
    {
        // Simulate a slow API call.
        await Task.Delay(2000, cancellationToken);

        if (Data.TryGetValue(cuisineId, out var recipes))
        {
            return recipes;
        }

        return new List<Recipe>();
    }
}

