@page "/recipes/{CuisineId:int}"
@using sv_75a3f7126767415d8b29d6df3071e08a.Models
@using sv_75a3f7126767415d8b29d6df3071e08a.Services
@rendermode InteractiveServer
@implements IDisposable
@inject IRecipeService RecipeService
@inject NavigationManager Nav
@inject ILogger<Recipes> Logger

<PageTitle>Recipes</PageTitle>

<h1>Recipes</h1>

<nav class="mb-3">
    <a href="/recipes/1" class="btn @(CuisineId == 1 ? "btn-primary" : "btn-outline-primary") me-1">Italian</a>
    <a href="/recipes/2" class="btn @(CuisineId == 2 ? "btn-primary" : "btn-outline-primary") me-1">Mexican</a>
    <a href="/recipes/3" class="btn @(CuisineId == 3 ? "btn-primary" : "btn-outline-primary")">Japanese</a>
</nav>

@if (_errorMessage is not null)
{
    <div class="alert alert-danger d-flex justify-content-between align-items-center" role="alert">
        <span>@_errorMessage</span>
        <button class="btn btn-outline-danger btn-sm" @onclick="RetryAsync">Retry</button>
    </div>
}
else if (_recipes is null)
{
    <div class="d-flex align-items-center gap-2 my-4">
        <div class="spinner-border text-primary" role="status"></div>
        <span>Loading recipes…</span>
    </div>
}
else
{
    @if (_isRefreshing)
    {
        <div class="alert alert-info py-1 px-2 d-inline-block mb-3" role="status">
            <small>Refreshing…</small>
        </div>
    }

    <div class="row row-cols-1 row-cols-md-2 g-3">
        @foreach (var recipe in DisplayedRecipes)
        {
            <div class="col">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text">@recipe.Description</p>
                        <span class="badge bg-secondary">@recipe.PrepTimeMinutes min</span>
                    </div>
                </div>
            </div>
        }
    </div>

    @if (!DisplayedRecipes.Any())
    {
        <p class="text-muted mt-3">No recipes found for this cuisine.</p>
    }
}

@code {
    [Parameter]
    public int CuisineId { get; set; }

    [SupplyParameterFromQuery(Name = "sort")]
    public string? Sort { get; set; }

    private List<Recipe>? _recipes;
    private string? _errorMessage;
    private bool _isRefreshing;
    private int _loadedCuisineId;

    private CancellationTokenSource? _cts;

    private IEnumerable<Recipe> DisplayedRecipes =>
        string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
            ? _recipes!.OrderByDescending(r => r.Id)
            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
                ? _recipes!.OrderBy(r => r.PrepTimeMinutes)
                : _recipes!;

    protected override Task OnParametersSetAsync()
    {
        // Only reload when the cuisine actually changes, not when sort changes.
        if (CuisineId != _loadedCuisineId)
        {
            return LoadRecipesAsync();
        }

        return Task.CompletedTask;
    }

    private async Task LoadRecipesAsync()
    {
        // Cancel any in-flight request for the previous cuisine.
        await CancelPendingRequestAsync();

        _cts = new CancellationTokenSource();
        var cancellationToken = _cts.Token;

        _errorMessage = null;

        // If we already have data on screen, show the refreshing indicator
        // instead of replacing content with a full loading placeholder.
        _isRefreshing = _recipes is not null;

        var targetCuisineId = CuisineId;

        try
        {
            var result = await RecipeService.GetByCuisineAsync(targetCuisineId, cancellationToken);

            // Guard against a late completion after cancellation.
            if (cancellationToken.IsCancellationRequested)
            {
                return;
            }

            _recipes = result;
            _loadedCuisineId = targetCuisineId;
        }
        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
        {
            // Expected when the user navigated to a different cuisine or left the page.
            return;
        }
        catch (TimeoutException ex)
        {
            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
            _errorMessage = "The request timed out. Please try again.";
        }
        catch (Exception ex)
        {
            Logger.LogError(ex, "Failed to load recipes for cuisine {CuisineId}", targetCuisineId);
            _errorMessage = "Something went wrong while loading recipes. Please try again.";
        }
        finally
        {
            _isRefreshing = false;
