+    private CancellationTokenSource? _cts;
+
+    private IEnumerable<Recipe> DisplayedRecipes =>
+        string.Equals(Sort, "newest", StringComparison.OrdinalIgnoreCase)
+            ? _recipes!.OrderByDescending(r => r.Id)
+            : string.Equals(Sort, "popular", StringComparison.OrdinalIgnoreCase)
+                ? _recipes!.OrderBy(r => r.PrepTimeMinutes)
+                : _recipes!;
+
+    protected override Task OnParametersSetAsync()
+    {
+        // Only reload when the cuisine actually changes, not when sort changes.
+        if (CuisineId != _loadedCuisineId)
+        {
+            return LoadRecipesAsync();
+        }
+
+        return Task.CompletedTask;
+    }
+
+    private async Task LoadRecipesAsync()
+    {
+        // Cancel any in-flight request for the previous cuisine.
+        await CancelPendingRequestAsync();
+
+        _cts = new CancellationTokenSource();
+        var cancellationToken = _cts.Token;
+
+        _errorMessage = null;
+
+        // If we already have data on screen, show the refreshing indicator
+        // instead of replacing content with a full loading placeholder.
+        _isRefreshing = _recipes is not null;
+
+        var targetCuisineId = CuisineId;
+
+        try
+        {
+            var result = await RecipeService.GetByCuisineAsync(targetCuisineId, cancellationToken);
+
+            // Guard against a late completion after cancellation.
+            if (cancellationToken.IsCancellationRequested)
+            {
+                return;
+            }
+
+            _recipes = result;
+            _loadedCuisineId = targetCuisineId;
+        }
+        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
+        {
+            // Expected when the user navigated to a different cuisine or left the page.
+            return;
+        }
+        catch (TimeoutException ex)
+        {
+            Logger.LogError(ex, "Timeout loading recipes for cuisine {CuisineId}", targetCuisineId);
+            _errorMessage = "The request timed out. Please try again.";
+        }
+        catch (Exception ex)
+        {
+            Logger.LogError(ex, "Failed to load recipes for cuisine {CuisineId}", targetCuisineId);
+            _errorMessage = "Something went wrong while loading recipes. Please try again.";
+        }
+        finally
+        {
+            _isRefreshing = false;
+        }
+    }
+
+    private Task RetryAsync() => LoadRecipesAsync();
+
+    private async Task CancelPendingRequestAsync()
+    {
+        if (_cts is not null)
+        {
+            await _cts.CancelAsync();
+            _cts.Dispose();
+            _cts = null;
+        }
+    }
+
+    public void Dispose()
+    {
+        _cts?.Cancel();
+        _cts?.Dispose();
+        _cts = null;
+    }
+}
